import os, shutil, stat

def remove_readonly(func, path, exc_info):
    try:
        os.chmod(path, stat.S_IWRITE)
        func(path)
    except Exception:
        pass

def clean_dir(target_dir):
    if os.path.exists(target_dir):
        shutil.rmtree(target_dir, onexc=remove_readonly)

